{"function": "() => {
  // Find the studio albums table
  const tables = document.querySelectorAll('table');
  let studioAlbumsTable = null;

  // Look for table that has "Year" and "Album details" headers
  for (let table of tables) {
    const headers = table.querySelectorAll('th');
    let hasYear = false;
    let hasAlbumDetails = false;

    for (let header of headers) {
      const text = header.textContent.trim();
      if (text === 'Year') hasYear = true;
      if (text === 'Album details') hasAlbumDetails = true;
    }

    if (hasYear && hasAlbumDetails) {
      // Check if preceding heading is "Studio albums"
      const prevHeading = table.closest('h3');
      if (prevHeading && prevHeading.textContent.includes('Studio albums')) {
        studioAlbumsTable = table;
        break;
      }

      // Also check for preceding siblings
      let prev = table.previousElementSibling;
      while (prev) {
        if (prev.tagName === 'H3' && prev.textContent.includes('Studio albums')) {
          studioAlbumsTable = table;
          break;
        }
        prev = prev.previousElementSibling;
      }
    }
  }

  if (!studioAlbumsTable) return 'Table not found';

  // Extract rows
  const rows = studioAlbumsTable.querySelectorAll('tr');
  const albums = [];

  for (let row of rows) {
    const cells = row.querySelectorAll('td');
    if (cells.length >= 2) {
      const yearCell = cells[0];
      const albumCell = cells[1];

      const year = yearCell.textContent.trim();
      const album = albumCell.textContent.trim();

      // Extract album name (remove label info)
      let albumName = album.split('Label:')[0].trim();

      albums.push({ year, album: albumName });
    }
  }

  return albums;
}"}

