{"function": "() => {
  // Try to locate the studio albums section by finding the heading
  const headings = document.querySelectorAll('h2, h3, h4');
  let targetHeading = null;

  for (let heading of headings) {
    if (heading.textContent.includes('Studio albums')) {
      targetHeading = heading;
      break;
    }
  }

  if (!targetHeading) return 'No Studio albums heading found';

  // Find the next table after this heading
  let nextElement = targetHeading.nextElementSibling;
  let table = null;

  while (nextElement) {
    if (nextElement.tagName === 'TABLE') {
      table = nextElement;
      break;
    }
    nextElement = nextElement.nextElementSibling;
  }

  if (!table) return 'No table found after Studio albums heading';

  // Now extract data from the table
  const rows = table.querySelectorAll('tr');
  const albums = [];

  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];
    const cells = row.querySelectorAll('td, th');

