  // Look for the discography section
  const allText = document.body.innerText;
  const discographyIndex = allText.indexOf('Discography');

  if (discographyIndex === -1) return 'Discography section not found';

  // Try to extract studio albums information by finding the pattern
  const studioAlbumsIndex = allText.indexOf('Studio albums');
  if (studioAlbumsIndex === -1) return 'Studio albums section not found';

  // Get text from Studio albums to the next section
  const textFromStudioAlbums = allText.substring(studioAlbumsIndex);

  // Look for the next heading after Studio albums
  const nextHeadings = ['EPs', 'Live albums', 'Compilation albums', 'Filmography'];
  let endIndex = textFromStudioAlbums.length;

  for (let heading of nextHeadings) {
    const idx = textFromStudioAlbums.indexOf(heading);
    if (idx !== -1 && idx < endIndex) {
      endIndex = idx;
    }
  }

  const studioAlbumsText = textFromStudioAlbums.substring(0, endIndex);

  // Parse the text to find year-album pairs
  const lines = studioAlbumsText.split('\n');
  const albums = [];

  for (let line of lines) {
    line = line.trim();

    // Look for lines that start with 4-digit year
    const yearMatch = line.match(/^(\d{4})\s+(.+)/);
    if (yearMatch) {
      const year = yearMatch[1];
      let album = yearMatch[2];

      // Remove "Label:" and everything after it
      const labelIndex = album.indexOf('Label:');
      if (labelIndex !== -1) {
        album = album.substring(0, labelIndex).trim();
      }

      albums.push({ year, album });
    }
  }

  return albums;
}"}

